package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes SETTING_CHANGED to the audit file once the setting is stored (value= blank for none; from=<date> at its
 *  end when a from-date was given). Then writes the figures the change moved (see Rollup). */
public class RecordSettingChanged {
    public void record(@Val Setting setting, @Val SettingValues values, @Val RollupBefore before, Rollup rollup,
            Audit audit) {
        audit.record("SETTING_CHANGED sheet=" + setting.sheetId() + " by=" + values.by() + " key=" + setting.key()
                + " value=" + (setting.value() == null ? "" : setting.value())
                + (values.dated() && values.from() != null ? " from=" + values.from() : ""));
        rollup.record(setting.sheetId(), values.by(), before);
    }
}
package net.officefloor.hq.app.period;

import java.util.LinkedHashMap;
import java.util.Map;

/** A period as sent to the screen: its dates as yyyy-MM-dd, whether it is closed or soft-closed and, either, its fixed due-total
 *  and each person's fixed due-total for it, by person id (a person not listed shows 0.00). */
public record PeriodResponse(long id, String sheetId, String name, String from, String to, boolean closed, boolean soft,
        String closedTotal, Map<String, String> personTotals) {
    public static PeriodResponse from(Period period, PeriodRepository periods) {
        Map<String, String> totals = new LinkedHashMap<>();
        if (period.closed() || period.soft()) {
            periods.personTotals(period).forEach((id, total) -> totals.put(String.valueOf(id), total.toPlainString()));
        }
        return new PeriodResponse(period.id(), period.sheetId(), period.name(), period.from().toString(),
                period.to().toString(), period.closed(), period.soft(),
                period.closedTotal() == null ? null : period.closedTotal().toPlainString(), totals);
    }

    /** The period as it stood at the end of a date, in the state it had then (see PeriodRepository#listAsOf). */
    public static PeriodResponse from(Period period, PeriodRepository.StateAsOf state) {
        Map<String, String> totals = new LinkedHashMap<>();
        if (state.closed() || state.soft()) {
            state.personTotals().forEach((id, total) -> totals.put(String.valueOf(id), total.toPlainString()));
        }
        return new PeriodResponse(period.id(), period.sheetId(), period.name(), period.from().toString(),
                period.to().toString(), state.closed(), state.soft(),
                state.closedTotal() == null ? null : state.closedTotal().toPlainString(), totals);
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's periods, by from-date; read as of a date (see AsOf), as they stood then. */
public class RespondWithPeriods {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(value = "asOf", required = false) String asOf, PeriodRepository periods,
            ObjectResponse<List<PeriodResponse>> response) {
        LocalDate date = AsOf.parse(asOf);
        response.send(date == null
                ? periods.list(sheetId.trim()).stream().map((p) -> PeriodResponse.from(p, periods)).toList()
                : periods.listAsOf(sheetId.trim(), date).entrySet().stream()
                        .map((e) -> PeriodResponse.from(e.getKey(), e.getValue())).toList());
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithGeneratedPeriods {
    public void respond(@Val GeneratedPeriods generated, ObjectResponse<GeneratedPeriods> response) {
        response.send(generated);
    }
}
