import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { nowKey, useReadNow } from '../../query/readNow';
import type { Late } from '../overdue/late';
import { gradeOn, usePeople } from '../people/people';
import { useSheetToday } from '../session/session';

/** A sheet setting: `value` is text (clerk-limit, cap, floor: an amount with two decimals; terms, terms-A, terms-B, terms-C: a whole number of days; late-pct: a percent with two decimals; grace-A, grace-B, grace-C: a whole number of days; policy-date, period-numbering-from, entry-date: yyyy-MM-dd), null when blank.
 *  `from` is the date the value is in force from (yyyy-MM-dd); null when undated (policy-date, period-numbering-from, entry-date, or a
 *  value from before settings were dated: in force on every date). */
export type Setting = { sheetId: string; key: string; value: string | null; from: string | null };

export const settingsKey = (sheetId: string) => ['sheet', sheetId, 'settings'];

/** The sheet's settings: every value recorded, by key then from-date. */
export function useSettings(sheetId: string) {
  const now = useReadNow();
  return useQuery({
    queryKey: nowKey(settingsKey(sheetId), now),
    queryFn: () => getJson<Setting[]>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`, now),
  });
}

/** The setting recorded for the key in force on the date (the latest from-date on or before it; an undated one is in
 *  force on every date); undefined when none is. */
export function inForce(settings: Setting[] | undefined, key: string, date: string): Setting | undefined {
  let found: Setting | undefined;
  for (const s of settings ?? []) {
    if (s.key !== key || (s.from !== null && s.from > date)) continue;
    if (found === undefined || (s.from !== null && (found.from === null || s.from > found.from))) found = s;
  }
  return found;
}

/** A dated figure: its value in force on a date (yyyy-MM-dd). */
export type Dated = (date: string) => string;

/** The floor a sheet has until one is set. */
export const DEFAULT_FLOOR = '1.00';

/** The sheet's floor: the least a claim's live due may be (two decimals), the one in force on the claim's date. */
export function useFloor(sheetId: string): Dated {
  const settings = useSettings(sheetId);
  return (date) => inForce(settings.data, 'floor', date)?.value ?? DEFAULT_FLOOR;
}

/** The sheet's cap in force on its today: the most a person's due-total may be (two decimals); null when blank (none). */
export function useCap(sheetId: string): string | null {
  const settings = useSettings(sheetId);
  const today = useSheetToday(sheetId);
  return inForce(settings.data, 'cap', today)?.value ?? null;
}

/** The terms a sheet has until they are set. */
export const DEFAULT_TERMS = '14';


/** The late percent a sheet has until one is set. */
export const DEFAULT_LATE_PCT = '0.00';

/** What the sheet's late charge depends on: its today, its late percent (the one in force on each 30-day boundary of an overdue claim), its
 *  policy date (its today while blank), which decides how claims round, and each claim's grace: grace-A, grace-B or grace-C (whole days,
 *  blank for none) of its person's grade in force on its date, the one in force on that date. */
export function useLate(sheetId: string): Late {
  const settings = useSettings(sheetId);
  const people = usePeople(sheetId);
  const today = useSheetToday(sheetId);
  const policy = settings.data?.find((s) => s.key === 'policy-date')?.value ?? today;
  const grace = (claim: { personId: number; date: string }) => {
    const person = people.data?.find((p) => p.id === claim.personId);
    const value = person === undefined ? null : inForce(settings.data, `grace-${gradeOn(person, claim.date)}`, claim.date)?.value;
    return value === null || value === undefined ? 0 : Number(value);
  };
  return { today, pct: (date) => inForce(settings.data, 'late-pct', date)?.value ?? DEFAULT_LATE_PCT, policy, grace };
}
import { useRef, useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPage } from '../../slots/defs/sheetPage';
import { poolsKey } from '../pools/pools';
import { useSheetToday } from '../session/session';
import { DEFAULT_FLOOR, DEFAULT_LATE_PCT, DEFAULT_TERMS, inForce, settingsKey, useSettings, type Setting } from './settings';

const GRADES = ['A', 'B', 'C'] as const;
type GradeTerms = `terms-${(typeof GRADES)[number]}`;
type GradeGrace = `grace-${(typeof GRADES)[number]}`;
type GradeProof = `proof-threshold-${(typeof GRADES)[number]}`;
const PERM_ACTIONS = ['open', 'settle', 'void', 'reassign', 'close', 'reopen'] as const;
type PermKey = `perm-${(typeof PERM_ACTIONS)[number]}`;
const PERM_KEYS: PermKey[] = PERM_ACTIONS.map((a) => `perm-${a}` as PermKey);
type Key = PermKey | 'clerk-limit' | 'cap' | 'proof-threshold' | 'note-threshold' | 'floor' | 'terms' | GradeTerms | GradeGrace | GradeProof | 'late-pct' | 'policy-date' | 'period-numbering-from' | 'entry-date' | 'grace-days' | 'pot' | 'parent';
const KEYS: Key[] = ['clerk-limit', 'cap', 'proof-threshold', 'note-threshold', 'floor', 'terms', 'terms-A', 'terms-B', 'terms-C', 'grace-A', 'grace-B', 'grace-C', 'proof-threshold-A', 'proof-threshold-B', 'proof-threshold-C', 'late-pct', 'policy-date', 'period-numbering-from', 'entry-date', 'grace-days', 'pot', 'parent', ...PERM_KEYS];
const BLANK: Record<Key, string> = {
  'clerk-limit': '', cap: '', 'proof-threshold': '', 'note-threshold': '', floor: '', terms: '', 'terms-A': '', 'terms-B': '', 'terms-C': '', 'grace-A': '', 'grace-B': '', 'grace-C': '', 'proof-threshold-A': '', 'proof-threshold-B': '', 'proof-threshold-C': '', 'late-pct': '', 'policy-date': '', 'period-numbering-from': '', 'entry-date': '', 'grace-days': '', pot: '', parent: '',
  ...(Object.fromEntries(PERM_KEYS.map((k) => [k, ''])) as Record<PermKey, string>),
};
/** The keys whose values are dated: each saved from a from-date (blank: the sheet's today). */
const DATED: Key[] = ['clerk-limit', 'cap', 'proof-threshold', 'note-threshold', 'floor', 'terms', 'terms-A', 'terms-B', 'terms-C', 'grace-A', 'grace-B', 'grace-C', 'proof-threshold-A', 'proof-threshold-B', 'proof-threshold-C', 'late-pct'];
const dated = (key: Key) => DATED.includes(key);

/** The sheet's settings: the clerk limit (the most a clerk may settle a claim's due for; blank for no limit) and the
 *  cap (the most a person's due-total may be; blank for none) and the proof threshold (a claim whose due is above
 *  the one in force on its date cannot be settled nor approved while it has no proofs; blank for none) and each grade's own proof threshold (a claim whose person has that grade on its date takes the grade's in force on that date instead of the sheet's; blank for none) and the note threshold (a claim whose due is above the one in force on its date cannot be
 *  opened while its note is empty; blank for none) and the floor (the least a claim's live due may be; 1.00 until set) and the terms (the days from a claim's date to its
 *  due-by, fixed when the claim is added; 14 until set) and each grade's own terms (a grade without its own has the
 *  sheet's) and each grade's grace (whole days added to the due-by of a claim whose person has that grade on its date, the one in force on that date, before
 *  it is overdue and its late charge counts; blank for none) and the late percent (what an overdue claim gains of its figure for every full 30 days
 *  overdue; 0.00 until set) and the policy date (yyyy-MM-dd; blank: the sheet's today — a claim dated before it rounds
 *  half up, one on or after it half to even) and the period numbering from-date (yyyy-MM-dd; blank: off — while the sheet's
 *  today is on or after it, a claim opened is numbered within its period) and the entry date (yyyy-MM-dd; blank: off — while set, a new claim given no
 *  date, by the claim form, the quick-add bar, a paste or a correction, is dated it instead of the sheet's today) and the pot (two decimals; blank: none — shared out as each balanced pool's cuts; undated) and the parent sheet (the id of a sheet that exists, not this one nor one with this one as an ancestor; blank: none — a grade with no rate in force on a date takes its parent's, then the parent's parent's, up to three levels up; undated) and the grace days (a whole number; blank: off — when the
 *  sheet's today changes, every open period whose to-date plus them is before the new today is closed) and the permission matrix (for each of open, settle,
 *  void, reassign, close and reopen, the roles that may take it, comma separated; blank: the standing rule — open, settle,
 *  void and close by clerk and steward, reassign and reopen by steward; undated). Every setting but the policy date, the
 *  period numbering from-date, the entry date, the grace days and the permissions is dated: saved with its from-date (blank: the sheet's today) it keeps the values from
 *  other dates, and what shows in force is the value on the sheet's today (a claim takes its floor, late percent and
 *  terms, and proof and note thresholds, from its own date). Saving stores the fields entered since the last save
 *  (a field focused counts, so a blank typed over a blank still saves), the clerk limit when none was. */
function Settings({ sheetId, user }: { sheetId: string; user: string }) {
  const settings = useSettings(sheetId);
  const queryClient = useQueryClient();
  const today = useSheetToday(sheetId);
  const [values, setValues] = useState<Record<Key, string>>(BLANK);
  const [froms, setFroms] = useState<Record<Key, string>>(BLANK);
  const touched = useRef(new Set<Key>());

  const submit = useSubmitOnce();
  const save = useMutation({
    mutationFn: async (entries: [Key, string, string][]) => {
      for (const [key, value, from] of entries) {
        await putJson<Setting>(`/api/sheets/${encodeURIComponent(sheetId)}/settings/${key}`, { value, from, by: user });
      }
    },
    onSuccess: () => {
      setValues(BLANK);
      setFroms(BLANK);
      touched.current.clear();
    },
    onSettled: (_data, _error, variables) => {
      submit.end();
      void queryClient.invalidateQueries({ queryKey: settingsKey(sheetId) });
      void queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) });
      // A new parent changes the sheet's parent and the rates it uses.
      if (variables.some(([key]) => key === 'parent')) void queryClient.invalidateQueries({ queryKey: ['sheet', sheetId] });
    },
  });
  const current = (key: Key) => (dated(key) ? inForce(settings.data, key, today) : settings.data?.find((s) => s.key === key))?.value ?? '';

  const field = (key: Key, label: string, inputMode: 'decimal' | 'numeric' | 'text' = 'decimal') => (
    <label>
      {label}{' '}
      <input
        data-testid={`setting-${key}`}
        inputMode={inputMode}
        value={values[key]}
        onFocus={() => touched.current.add(key)}
        onChange={(e) => {
          touched.current.add(key);
          const value = e.target.value;
          setValues((was) => ({ ...was, [key]: value }));
          save.reset();
        }}
      />
      {dated(key) && (
        <>
          {' '}from{' '}
          <input
            data-testid={`setting-${key}-from`}
            inputMode="numeric"
            placeholder="yyyy-MM-dd"
            value={froms[key]}
            onFocus={() => touched.current.add(key)}
            onChange={(e) => {
              touched.current.add(key);
              const from = e.target.value;
              setFroms((was) => ({ ...was, [key]: from }));
              save.reset();
            }}
          />
        </>
      )}
    </label>
  );

  return (
    <section data-testid="settings">
      <h3>Settings</h3>
      <form
        data-testid="settings-form"
        onSubmit={(e) => {
          e.preventDefault();
          if (!submit.begin()) return;
          save.reset();
          const keys = KEYS.filter((k) => touched.current.has(k));
          save.mutate((keys.length > 0 ? keys : (['clerk-limit'] as Key[])).map((k) => [k, values[k], froms[k]]));
        }}
      >
        {field('clerk-limit', 'Clerk limit')} {field('cap', 'Cap')} {field('proof-threshold', 'Proof threshold')} {field('note-threshold', 'Note threshold')} {field('floor', 'Floor')}{' '}
        {field('terms', 'Terms (days)', 'numeric')}{' '}
        {GRADES.map((g) => (
          <span key={g}>{field(`terms-${g}`, `Terms grade ${g} (days)`, 'numeric')} </span>
        ))}
        {GRADES.map((g) => (
          <span key={g}>{field(`grace-${g}`, `Grace grade ${g} (days)`, 'numeric')} </span>
        ))}
        {GRADES.map((g) => (
          <span key={`proof-${g}`}>{field(`proof-threshold-${g}`, `Proof threshold grade ${g}`)} </span>
        ))}
        {field('late-pct', 'Late %')}{' '}
        {field('policy-date', 'Policy date (yyyy-MM-dd)', 'numeric')}{' '}
        {field('period-numbering-from', 'Period numbering from (yyyy-MM-dd)', 'numeric')}{' '}
        {field('entry-date', 'Entry date (yyyy-MM-dd)', 'numeric')}{' '}
        {field('grace-days', 'Grace days', 'numeric')}{' '}
        {field('pot', 'Pot')}{' '}
        {field('parent', 'Parent sheet', 'text')}{' '}
        {PERM_ACTIONS.map((a) => (
          <span key={a}>{field(`perm-${a}`, `Roles that may ${a} (comma separated)`, 'text')} </span>
        ))}
        <button type="submit" data-testid="settings-save" disabled={save.isPending}>
          Save settings
        </button>
        {save.isError && (
          <span data-testid="settings-error">
            The from-date must be yyyy-MM-dd, or blank; the clerk limit must be an amount with up to two decimals, or blank; the cap, the proof threshold, a grade's proof threshold and the note threshold likewise; the floor an amount with up to two
            decimals; the terms, and a grade's terms, a whole number of days, 0 or more; a grade's grace a whole number of days, 0 or more, or blank; the late percent a percent with up to two decimals; the policy date yyyy-MM-dd, or blank; the period numbering from-date yyyy-MM-dd, or blank; the entry date yyyy-MM-dd, or blank; the grace days a whole number, 0 or more, or blank; the pot an amount with up to two decimals, or blank; a permission roles (clerk, steward) separated by commas, or blank; the parent a sheet that exists (has been loaded), not this sheet nor one that has this sheet as an ancestor, or blank.
          </span>
        )}
      </form>
      {settings.isError && <p data-testid="settings-load-error">Could not load settings.</p>}
      <p>
        Clerk limit in force <span data-testid="setting-clerk-limit-current">{current('clerk-limit')}</span>
      </p>
      <p>
        Cap in force <span data-testid="setting-cap-current">{current('cap')}</span>
      </p>
